import Foundation
import Observation

struct PackItem: Identifiable, Codable, Hashable {
    var id = UUID()
    var name: String
    var done = false
}

/// Day-by-day plan generated by the AI.
struct TripPlan: Codable, Hashable {
    struct Item: Codable, Hashable {
        let time: String
        let title: String
        let description: String
        let kind: String
    }
    struct Day: Codable, Hashable {
        let date: String
        let title: String
        let items: [Item]
    }
    let summary: String
    let days: [Day]
    let tips: [String]
    let packing: [String]
    let budget: String

    /// The model sometimes returns an empty skeleton – don't save that.
    var isUsable: Bool { !days.isEmpty && days.contains { !$0.items.isEmpty } }
}

struct Trip: Identifiable, Codable, Hashable {
    var id = UUID()
    var name: String
    var start: Date
    var end: Date
    var notes = ""
    var packing: [PackItem] = Trip.defaultPacking()
    var plan: TripPlan? = nil
    /// Last change on any device (for the sync between devices)
    var modified: Date? = nil
    /// Random id of the public trip page on the user's own server (nil = not shared)
    var shareToken: String? = nil

    static func defaultPacking() -> [PackItem] {
        [String(localized: "Pass / ID"), String(localized: "Handy-Ladekabel"), String(localized: "Powerbank"), String(localized: "Kopfhörer"),
         String(localized: "Reiseadapter"), String(localized: "Medikamente"), String(localized: "Zahnbürste & Kulturbeutel"),
         String(localized: "Kleider"), String(localized: "Kreditkarte & etwas Bargeld"), String(localized: "eSIM / Roaming geprüft"),
         String(localized: "Reiseversicherung"), String(localized: "Online eingecheckt")]
            .map { PackItem(name: $0) }
    }
}

@MainActor
@Observable
final class TripStore {
    static let shared = TripStore()
    private(set) var trips: [Trip] = []
    private let file = URL.documentsDirectory.appending(path: "trips.json")

    init() {
        let d = JSONDecoder()
        d.dateDecodingStrategy = .iso8601
        let loaded = SafeFile.load([Trip].self, from: file, decoder: d)
        writable = loaded.writable
        trips = loaded.value ?? []
    }

    @ObservationIgnored private var writable = true

    private func save() {
        guard writable else { return }
        let e = JSONEncoder()
        e.dateEncodingStrategy = .iso8601
        try? e.encode(trips).write(to: file, options: .atomic)
    }

    func upsert(_ trip: Trip) {
        var t = trip
        t.modified = Date()
        if let i = trips.firstIndex(where: { $0.id == t.id }) { trips[i] = t } else { trips.append(t) }
        trips.sort { $0.start > $1.start }
        save()
        DeviceSync.scheduleSync()
    }

    func delete(_ ids: [UUID]) {
        trips.removeAll { ids.contains($0.id) }
        save()
        DeviceSync.noteDeleted(ids)
    }

    /// Result of a sync with the other devices.
    func replaceAll(_ merged: [Trip]) {
        let sorted = merged.sorted { $0.start > $1.start }
        guard sorted != trips else { return }
        trips = sorted
        save()
    }

    func flights(for trip: Trip, in store: FlightStore) -> [Flight] {
        let cal = Calendar.current
        let start = cal.startOfDay(for: trip.start)
        let end = cal.date(byAdding: .day, value: 1, to: cal.startOfDay(for: trip.end)) ?? trip.end
        return store.flights.filter { $0.sortDate >= start && $0.sortDate < end }.sorted { $0.sortDate < $1.sortDate }
    }

    /// Suggests trips from flights that are not yet part of a trip (flights within 21 days of each other).
    func suggestions(from store: FlightStore) -> [Trip] {
        let covered = Set(trips.flatMap { flights(for: $0, in: store).map(\.id) })
        let free = store.flights.filter { !covered.contains($0.id) }.sorted { $0.sortDate < $1.sortDate }
        let home = HotelRoute.homeAirport
        var groups: [[Flight]] = []
        var closed = true
        for f in free {
            if !closed, let last = groups.last?.last, f.sortDate.timeIntervalSince(last.sortDate) < 21 * 86400 {
                groups[groups.count - 1].append(f)
            } else {
                groups.append([f])
            }
            // back home (or back where the trip started): the trip is complete, the next flight starts a new one
            let origin = groups[groups.count - 1][0].departure.code
            closed = f.arrival.code == origin || (!home.isEmpty && f.arrival.code == home)
        }
        return groups.map { g in
            // name: where you stayed longest (largest gap between landing and the next departure), not just the middle flight
            var best = g[0].arrival.displayCity
            var longest: TimeInterval = -1
            for (i, f) in g.enumerated() where i + 1 < g.count {
                let stay = g[i + 1].sortDate.timeIntervalSince(f.arrival.best ?? f.sortDate)
                if stay > longest && f.arrival.code != g[0].departure.code { longest = stay; best = f.arrival.displayCity }
            }
            return Trip(name: best, start: g.first!.sortDate, end: g.last!.arrival.best ?? g.last!.sortDate)
        }
        // only trips that are still ahead or running – past flights need no suggestion
        .filter { $0.end >= Date() }
    }
}

/// Files (boarding passes, bookings, …) stored per flight.
enum FlightDocs {
    static func folder(_ id: UUID) -> URL {
        let url = URL.documentsDirectory.appending(path: "docs/\(id.uuidString)")
        try? FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
        return url
    }

    static func list(_ id: UUID) -> [URL] {
        (try? FileManager.default.contentsOfDirectory(at: folder(id), includingPropertiesForKeys: [.creationDateKey]))?
            .sorted { $0.lastPathComponent < $1.lastPathComponent } ?? []
    }

    @discardableResult
    static func add(_ source: URL, to id: UUID) -> Bool {
        let scoped = source.startAccessingSecurityScopedResource()
        defer { if scoped { source.stopAccessingSecurityScopedResource() } }
        var target = folder(id).appending(path: source.lastPathComponent)
        if FileManager.default.fileExists(atPath: target.path()) {
            target = folder(id).appending(path: "\(Int(Date().timeIntervalSince1970))-\(source.lastPathComponent)")
        }
        return (try? FileManager.default.copyItem(at: source, to: target)) != nil
    }

    static func addImage(_ data: Data, to id: UUID) {
        let target = folder(id).appending(path: "Foto-\(Int(Date().timeIntervalSince1970)).jpg")
        try? data.write(to: target)
    }

    static func delete(_ url: URL) { try? FileManager.default.removeItem(at: url) }
}
